SELECT "users"."id", "users"."email", "users"."name", "users"."nickname", "users"."age", "users"."status", "users"."prev_status", "users"."balance", "users"."score", "users"."is_admin", "users"."tags", "users"."meta", "users"."settings", "users"."external_id", "users"."manager_id", "users"."birthday", "users"."created_at" FROM "users" WHERE EXISTS (SELECT "orders"."id", "orders"."user_id", "orders"."amount", "orders"."quantity", "orders"."note", "orders"."created_at" FROM "orders" WHERE "orders"."user_id" = "users"."id" AND "orders"."amount" > $1) AND "users"."id" IN (SELECT "orders"."user_id" FROM "orders" WHERE "orders"."quantity" > $2) AND "users"."name" = $3
-- args: []interface {}{pgtype.Numeric{Int:<nil>, Exp:0, NaN:false, InfinityModifier:0, Valid:false}, 1, "after"}
